{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} is your trusted dental home in {{CITY}}, {{STATE}}. Compassionate care, advanced technology, and beautiful results. Call {{PHONE}} to schedule.">
  <link rel="canonical" href="/index.html">
