    <div class="container navbar">
      <a class="brand" href="/index.html" aria-label="{{BUSINESS_NAME}} home">
        <span class="brand-logo" aria-hidden="true">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" focusable="false" aria-hidden="true"><path d="M12 2c3.6 0 7 1.7 9.2 4.6.4.5.4 1.2-.1 1.6l-5.5 5c-.7.6-1.8.3-2.1-.6l-.5-1.4c-.2-.4-.7-.6-1.1-.4l-1.2.6c-.8.4-1.7-.1-1.9-1l-.8-4c-.1-.6.2-1.2.8-1.4C9.8 2.4 10.9 2 12 2Z" fill="#fff"/><circle cx="18.5" cy="5.5" r="2.5" fill="#7fd3f0"/></svg>
        </span>
        <span class="brand-text">{{BUSINESS_NAME}}<small>{{TAGLINE}}</small></span>
      </a>
